import numpy as np

def softmax(x):
    e = np.exp(x - np.max(x))
    return e / np.sum(e)

def reinforce(env, episodes, alpha, gamma):
    n_states = env.n_states
    n_actions = env.n_actions
    theta = np.zeros((n_states, n_actions))
    episode_rewards = []
    for ep in range(episodes):
        state = env.reset()
        trajectory = []
        done = False
        while not done:
            probs = softmax(theta[state])
            action = np.random.choice(n_actions, p=probs)
            next_state, reward, done = env.step(action)
            trajectory.append((state, action, reward))
            state = next_state
        G = 0
        for state, action, reward in reversed(trajectory):
            G = reward + gamma * G
            probs = softmax(theta[state])
            theta[state][action] += alpha * G * (1 - probs[action])
            for a in range(n_actions):
                if a != action:
                    theta[state][a] -= alpha * G * probs[a]
        episode_rewards.append(sum(r for _, _, r in trajectory))
    return {"theta": theta, "episode_rewards": episode_rewards}
